  "quote.332": "The price of success is hard work, dedication to the job at hand.",
  "quote.333": "Practice does not make perfect. Only perfect practice makes perfect.",
  "quote.334": "Once you learn to quit, it becomes a habit.",
  "quote.335": "Adversity causes some men to break; others to break records.",
  "quote.336": "Do not let making a living prevent you from making a life.",
  "quote.337": "Ability may get you to the top, but it takes character to keep you there.",
  "quote.338": "Things turn out best for the people who make the best of the way things turn out.",
  "quote.339": "If you don't have time to do it right, when will you have time to do it over?",
  "quote.340": "Never mistake activity for achievement.",
  "quote.341": "Don't measure yourself by what you have accomplished, but by what you should have accomplished with your ability.",
  "quote.342": "The road to success is always under construction.",
  "quote.343": "I've learned that something constructive comes from every defeat.",
  "quote.344": "Leadership is getting someone to do what they don't want to do, to achieve what they want to achieve.",
  "quote.345": "A trophy carries dust. Memories last forever.",
  "quote.346": "Gold medals are made out of your sweat, blood and tears and effort in the gym every day.",
  "quote.347": "Hard days are the best because that's when champions are made.",
  "quote.348": "I'm not the next Usain Bolt or Michael Phelps. I'm the first Simone Biles.",
  "quote.349": "Dreams don't work unless you do.",
  "quote.350": "Small disciplines repeated with consistency every day lead to great achievements gained slowly over time.",
  "quote.351": "You'll never change your life until you change something you do daily.",
  "quote.352": "Nothing is particularly hard if you divide it into small jobs.",
  "quote.353": "Keep your eyes on the stars, and your feet on the ground.",
  "quote.354": "The only man who never makes a mistake is the man who never does anything.",
  "quote.355": "Act as if what you do makes a difference. It does.",
  "quote.356": "Act as if it were impossible to fail.",
  "quote.357": "The harder the conflict, the more glorious the triumph.",
  "quote.358": "What we obtain too cheap, we esteem too lightly.",
  "quote.359": "Determine never to be idle.",
  "quote.360": "Courage is grace under pressure.",
  "quote.361": "You may encounter many defeats, but you must not be defeated.",
  "quote.362": "Do the best you can until you know better. Then when you know better, do better.",
  "quote.363": "Success is liking yourself, liking what you do, and liking how you do it.",
  "quote.364": "The most difficult thing is the decision to act; the rest is merely tenacity.",
  "quote.365": "Alone we can do so little; together we can do so much.",
  "quote.366": "Character cannot be developed in ease and quiet.",
  "quote.367": "Although the world is full of suffering, it is also full of the overcoming of it.",
  "quote.368": "Knowledge is power.",
  "quote.369": "He that will not apply new remedies must expect new evils.",
  "quote.370": "Victorious warriors win first and then go to war.",
  "quote.371": "Absorb what is useful, discard what is useless, and add what is specifically your own.",
  "quote.372":
    "If you always put limits on everything you do, physical or anything else, it will spread into your work and into your life.",
  "quote.373":
    "For me life is continuously being hungry. The meaning of life is not simply to exist, to survive, but to move ahead, to go up, to conquer.",
  "quote.374": "Light weight, baby!",
  "quote.375": "A river cuts through rock not because of its power, but because of its persistence.",
  "quote.376": "Strength and growth come only through continuous effort and struggle.",
  "quote.377": "Patience, persistence and perspiration make an unbeatable combination for success.",
  "quote.378": "The starting point of all achievement is desire.",
